"""Maintain public business identity without touching PFA Studio or private files."""
from pathlib import Path
import re
from html import escape
ROOT = Path(__file__).resolve().parents[1]
NAME = 'PFA Praxis Science Lab'
EMAIL = 'contact@praxissciencelab.app'
ADDRESS = 'Brăila, Str. Ion C. Brătianu, nr. 1, postal code 810067, Romania'
MAIL = f'<a href="mailto:{EMAIL}">{EMAIL}</a>'
PAGES = {
 'contact': ('Contact', 'Contact details and support for PFA Praxis Science Lab.', f'''
<h2>Contact PFA Praxis Science Lab</h2><p>The Praxis Science Lab website belongs to <strong>{NAME}</strong>. Here you can find our apps, projects and public documentation.</p><dl><dt>Business name</dt><dd>{NAME}</dd><dt>Contact email</dt><dd>{MAIL}</dd><dt>Business address</dt><dd><address>{ADDRESS}</address></dd></dl>
<h2>App support</h2><p>Email us the app name, version, device model and a description of the issue. If you attach screenshots, remove personal information first. Do not send passwords, authentication codes, banking details or sensitive documents.</p><p>You can also visit each app's support page in <a href="../#apps">our catalog</a>. For personal data inquiries, use the same email address and mention the app or service concerned.</p><h2>Collaborations and other inquiries</h2><p>For proposals, questions about projects or information about this website, email {MAIL}. This is the primary contact address for the business.</p>'''),
 'legal': ('About & Legal Information', 'Business identity and address of the Praxis Science Lab website operator.', f'''
<h2>Website operator</h2><p>The website <a href="https://praxissciencelab.app/">praxissciencelab.app</a> is owned and operated by <strong>{NAME}</strong>.</p><dl><dt>Displayed business name</dt><dd>{NAME}</dd><dt>Business structure</dt><dd>Romanian sole proprietor (PFA)</dd><dt>Business address</dt><dd><address>{ADDRESS}</address></dd><dt>Email</dt><dd>{MAIL}</dd></dl><h2>Our work</h2><p>Praxis Science Lab presents apps and digital projects for science, education, creativity and everyday tasks. Each project's page indicates its availability and development status.</p><h2>Useful information</h2><ul><li><a href="../contact/">Contact and support</a></li><li><a href="../privacy/">Website privacy</a></li><li><a href="../terms/">Terms of Use</a></li></ul><p>App policies are available separately on their respective pages. Information on this website does not replace the specific terms of an app or the store through which it is distributed.</p>'''),
 'terms': ('Terms of Use', 'Terms of use for the public PFA Praxis Science Lab website.', f'''
<p>Last updated: October 6, 2026. These terms apply to the public website praxissciencelab.app, operated by {NAME}. Contact: {MAIL}.</p><h2>Purpose of this website</h2><p>This website presents apps, projects, documentation and support information. Listing a project as in development or testing does not mean that it is available for purchase or has a guaranteed release date.</p><h2>Apps and external stores</h2><p>Downloads, purchases, subscriptions and any refunds are governed by the terms applicable to the product and the distribution channel used. Check the description and terms displayed before making a purchase. These website terms do not restrict consumers' statutory rights.</p><h2>Content and use</h2><p>Respect the copyright and licenses specified for text, images, code and apps. Access to a file or code repository does not automatically grant a general license to reuse it. Third-party trademarks belong to their respective owners.</p><p>Do not use this website to attempt unauthorized access, disrupt services or submit unlawful content. Educational tools and general information should be used in their intended context and do not replace professional advice for medical, legal or financial decisions.</p><h2>Updates and external links</h2><p>Content may be corrected or updated. External services have their own terms and privacy policies. If you notice an error or a problem, let us know through the <a href="../contact/">contact page</a>.</p><h2>Personal data</h2><p>See the <a href="../privacy/">website privacy notice</a> and the separate privacy policy for the app you use.</p>'''),
}
PRIVACY = f'''<p>Effective date: 2026-11-06. This notice covers the public Praxis Science Lab website.</p><h2>Who operates this website</h2><p>The website is owned and operated by <strong>{NAME}</strong>, a Romanian sole proprietor (PFA), at {ADDRESS}. Contact for privacy and support: {MAIL}.</p><h2>Website operation and browser storage</h2><p>This static public website has no visitor account, contact form, advertising or analytics script added by Praxis Science Lab. It stores your selected color theme in browser local storage to remember your preference. You can remove this setting using your browser’s site-data controls. We do not add advertising or analytics cookies to this public site.</p><p>The main domain is hosted by Vercel. Delivering and securing pages involves ordinary technical connection information, such as IP address and request information. See <a href="https://vercel.com/legal/privacy-notice">Vercel’s privacy notice</a>. Legacy website addresses redirect through GitHub Pages, whose hosting is subject to <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy information</a>. Hosting providers may process information outside the European Economic Area under the safeguards described in their policies.</p><h2>Email and support</h2><p>If you email us, we receive your email address and the information you provide. We use correspondence to answer requests and resolve issues. Depending on the request, the basis is our legitimate interest in responding and maintaining services, steps requested before a contract or performance of a contract, or a legal obligation. We do not use support correspondence for advertising or sell it.</p><p>Access is limited to what is needed to handle your request and operate the supporting email/hosting services. Correspondence is retained as needed to resolve the request and meet applicable legal obligations; retention depends on the request and any continuing dispute or obligation. Do not send passwords, authentication codes, medical records or other unnecessary sensitive information.</p><h2>Your rights</h2><p>You may request access, correction, deletion, restriction or portability of applicable personal data, and object to processing based on legitimate interests, by contacting {MAIL}. Rights depend on the applicable legal conditions; we may need to verify a request. You may also complain to the Romanian supervisory authority, <a href="https://www.dataprotection.ro/">ANSPDCP</a>.</p><h2>Apps, private administration and external links</h2><p>App-specific privacy policies describe the information used by each app. This notice concerns the public presentation website; private PFA administration has separate authenticated access and is not a public visitor service. External websites and stores have their own policies. GitHub issues are public; do not post private information there.</p><h2>Updates</h2><p>The effective date changes when this notice is revised. For contact details, see <a href="../contact/">Contact</a>.</p>'''

def build():
    template=(ROOT/'privacy/index.html').read_text(encoding='utf-8')
    for slug,(title,description,body) in PAGES.items():
        html=re.sub(r'<title>.*?</title>',f'<title>{title} | Praxis Science Lab</title>',template,flags=re.S)
        html=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{escape(description,quote=True)}">',html)
        back = 'Back to home'
        main=f'<main id="main" class="document"><a class="back-link" href="../">← {back}</a><p class="eyebrow">PFA PRAXIS SCIENCE LAB</p><h1>{title}</h1><p class="document-lead">{description}</p>{body}</main>'
        html=re.sub(r'<main\b.*?</main>',lambda m:main,html,flags=re.S)
        path=ROOT/slug/'index.html';path.parent.mkdir(exist_ok=True);path.write_text(html,encoding='utf-8')
    privacy=re.sub(r'(<p class="document-lead">.*?</p>).*?(<div class="document-return">)',lambda m:m[1]+PRIVACY+m[2],template,flags=re.S)
    (ROOT/'privacy/index.html').write_text(privacy,encoding='utf-8')
    from seo import public_pages
    for path in public_pages():
        html=path.read_text(encoding='utf-8').replace('traiananghel@gmail.com',EMAIL)
        html=html.replace('Praxis Science Lab is the publishing brand used by Traian Anghel.',f'This website and the Praxis Science Lab publishing activity are operated by {NAME}.')
        depth=len(path.relative_to(ROOT).parts)-1;prefix='../'*depth
        navigation=f'<nav aria-label="Main navigation"><a href="{prefix}apps/">Our apps</a><a href="{prefix}projects/">Web projects</a><a href="{prefix}legal/">About</a><a href="{prefix}contact/">Contact</a></nav>'
        html=re.sub(r'<nav aria-label="Main navigation">.*?</nav>',lambda m:navigation,html,flags=re.S)
        footer=f'''<footer class="site-footer business-footer"><div><p>© <span id="copyright-years">2026</span> {NAME}</p><p>Website owned and operated by {NAME}.</p><address>{ADDRESS}</address><p>{MAIL}</p></div><nav aria-label="Business information"><a href="{prefix}contact/">Contact</a><a href="{prefix}legal/">PFA / Legal</a><a href="{prefix}privacy/">Website privacy</a><a href="{prefix}terms/">Terms of Use</a></nav></footer>'''
        html=re.sub(r'<footer class="site-footer[^\"]*">.*?</footer>',lambda m:footer,html,flags=re.S)
        if path==ROOT/'index.html':
            text=f'<p class="business-intro">This website belongs to <strong>{NAME}</strong>. <a href="contact/">Contact &amp; business details →</a></p>'
            if 'class="business-intro"' not in html:html=html.replace('<h2 id="support-title">Questions or feedback?</h2>','<h2 id="support-title">Questions or feedback?</h2>'+text)
        path.write_text(html,encoding='utf-8')
    print('Public PFA identity, contact, legal, terms and website privacy updated.')

if __name__=='__main__':
    build()
    from seo import build as seo_build
    seo_build()
